print("=" * 90)

# ------------------------------------------------------------
# 1. Candidate feature columns actually present in common_df
# ------------------------------------------------------------

candidate_cols = [
    b for b in candidate_registry["band_name"].tolist()
    if b in common_df.columns
]

print("\nCandidate features expected :", len(candidate_registry))
print("Candidate features present  :", len(candidate_cols))


# ------------------------------------------------------------
# 2. Build feature-level audit
# ------------------------------------------------------------

audit_rows = []

for band in candidate_cols:

    family = registry.loc[
        registry["band_name"] == band,
        "feature_family"
    ].iloc[0]

    status = registry.loc[
        registry["band_name"] == band,
        "feature_status"
    ].iloc[0]

    s = common_df[band]

    n_total = len(s)
    n_missing = s.isna().sum()
    n_valid = n_total - n_missing
    n_unique = s.dropna().nunique()

    missing_pct = (n_missing / n_total) * 100
    unique_ratio_pct = (
        (n_unique / n_valid) * 100
        if n_valid > 0 else np.nan
    )

    # Information-content flag
    if n_valid == 0:
        info_flag = "ALL_MISSING"
    elif n_unique <= 1:
        info_flag = "CONSTANT"
    elif n_unique <= 5:
        info_flag = "VERY_LOW_UNIQUE"
    elif n_unique <= 10:
        info_flag = "LOW_UNIQUE"
    else:
        info_flag = "OK"

    audit_rows.append({
        "feature_family": family,
        "band_name": band,
        "feature_status": status,
        "n_total": n_total,
        "n_valid": n_valid,
        "n_missing": n_missing,
        "missing_pct": missing_pct,
        "n_unique": n_unique,
        "unique_ratio_pct": unique_ratio_pct,
        "info_flag": info_flag
    })


