import pandas as pd
import numpy as np

print("=" * 90)
print("30F-B07 | FINE / INTERMEDIATE SPATIAL FEATURE SCREENING")
print("=" * 90)

# ------------------------------------------------------------
# 1. Defragment dataframe
# ------------------------------------------------------------

analysis_df = common_df.copy()


# ------------------------------------------------------------
# 2. Transform circular aspect
# ------------------------------------------------------------

aspect_rad = np.deg2rad(analysis_df["ASPECT_DEG"])

analysis_df["ASPECT_SIN"] = np.sin(aspect_rad)
analysis_df["ASPECT_COS"] = np.cos(aspect_rad)


# ------------------------------------------------------------
# 3. Build fine/intermediate numeric feature pool
# ------------------------------------------------------------

fine_families = [
    "TERRAIN",
    "HYDROLOGY",
    "SOIL",
    "SOIL_WATER"
]

fine_cols = (
    candidate_registry.loc[
        candidate_registry["feature_family"].isin(fine_families),
        "band_name"
    ]
    .tolist()
)

fine_cols = [
    c for c in fine_cols
    if c in analysis_df.columns
]

# Raw aspect is circular → replace by sin/cos
fine_cols = [
    c for c in fine_cols
    if c != "ASPECT_DEG"
]

fine_cols += [
    "ASPECT_SIN",
    "ASPECT_COS"
]

# Remove constant features if any
fine_cols = [
    c for c in fine_cols
    if analysis_df[c].dropna().nunique() > 1
]

print("\nFine/intermediate numeric features:", len(fine_cols))


# ------------------------------------------------------------
# 4. Helper: feature family
# ------------------------------------------------------------

def get_family(feature):

    if feature in ["ASPECT_SIN", "ASPECT_COS"]:
        return "TERRAIN"

    match = registry.loc[
        registry["band_name"] == feature,
        "feature_family"
    ]

    if len(match) == 0:
        return "UNKNOWN"

    return match.iloc[0]


# ------------------------------------------------------------
# 5. Spearman association with RISK_SCORE
# ------------------------------------------------------------

target = "RISK_SCORE_0_100"

screen_rows = []

for feature in fine_cols:

    pair = analysis_df[
        [feature, target]
    ].dropna()

    rho = pair[feature].corr(
        pair[target],
        method="spearman"
    )

    n_valid = len(pair)
    n_unique = pair[feature].nunique()

    if pd.isna(rho):
        strength = "NA"
    elif abs(rho) >= 0.50:
        strength = "STRONG"
    elif abs(rho) >= 0.30:
        strength = "MODERATE"
    elif abs(rho) >= 0.10:
        strength = "WEAK"
    else:
        strength = "VERY_WEAK"

    screen_rows.append({
        "feature_family": get_family(feature),
        "feature": feature,
        "n_valid": n_valid,
        "n_unique": n_unique,
        "spearman_rho": rho,
        "abs_rho": abs(rho) if not pd.isna(rho) else np.nan,
        "association_strength": strength
    })


fine_screen_df = (
    pd.DataFrame(screen_rows)
    .sort_values(
        "abs_rho",
        ascending=False
    )
    .reset_index(drop=True)
)


# ------------------------------------------------------------
# 6. Display strongest associations
# ------------------------------------------------------------

print("\n" + "-" * 90)
print("TOP 25 ASSOCIATIONS WITH RISK_SCORE_0_100")
print("-" * 90)

display(
    fine_screen_df.head(25)
)


# ------------------------------------------------------------
# 7. Summary by family
# ------------------------------------------------------------

print("\n" + "-" * 90)
print("ASSOCIATION SUMMARY BY FAMILY")
print("-" * 90)

family_summary = (
    fine_screen_df
    .groupby("feature_family")
    .agg(
        feature_count=("feature", "count"),
        median_abs_rho=("abs_rho", "median"),
        max_abs_rho=("abs_rho", "max")
    )
    .reset_index()
    .sort_values(
        "max_abs_rho",
        ascending=False
    )
)

display(family_summary)


# ------------------------------------------------------------
# 8. Pairwise feature redundancy
# ------------------------------------------------------------

print("\n" + "-" * 90)
print("HIGH REDUNDANCY PAIRS | ABS SPEARMAN >= 0.90")
print("-" * 90)

corr_matrix = (
    analysis_df[fine_cols]
    .corr(method="spearman")
)

redundancy_rows = []

for i in range(len(fine_cols)):
    for j in range(i + 1, len(fine_cols)):

        f1 = fine_cols[i]
        f2 = fine_cols[j]

        rho = corr_matrix.loc[f1, f2]

        if pd.notna(rho) and abs(rho) >= 0.90:

            redundancy_rows.append({
                "feature_1": f1,
                "feature_2": f2,
                "spearman_rho": rho,
                "abs_rho": abs(rho)
            })


redundancy_df = (
    pd.DataFrame(redundancy_rows)
)

if len(redundancy_df) > 0:

    redundancy_df = (
        redundancy_df
        .sort_values(
            "abs_rho",
            ascending=False
        )
        .reset_index(drop=True)
    )

    print(
        "Number of highly redundant pairs:",
        len(redundancy_df)
    )

    display(
        redundancy_df.head(40)
    )

else:

    print("No pairs with |rho| >= 0.90")


# ------------------------------------------------------------
# 9. Screening summary
# ------------------------------------------------------------

print("\n" + "-" * 90)
print("SCREENING SUMMARY")
print("-" * 90)

display(
    fine_screen_df[
        "association_strength"
    ]
    .value_counts()
    .rename_axis("association_strength")
    .reset_index(name="feature_count")
)

print("""
IMPORTANT:
- Spearman rho here measures association with the existing 30D04 risk score.
- It is NOT field-validation accuracy and NOT evidence of causality.
- Spatial autocorrelation is not yet corrected at this stage.
- Statistical significance/p-values are intentionally not used here.
""")

