# ============================================================
# 7. Restore coordinate + deterministic spatial group IDs
# ============================================================

def add_sample_metadata(feature):

    geom_utm = (
        feature
        .geometry()
        .transform(
            "EPSG:32647",
            1
        )
    )

    coords = ee.List(
        geom_utm.coordinates()
    )

    x = ee.Number(
        coords.get(0)
    )

    y = ee.Number(
        coords.get(1)
    )


    # --------------------------------------------------------
    # Deterministic SAMPLE_ID from UTM pixel-center coordinate
    # --------------------------------------------------------

    sample_id = (
        ee.String("S_")
        .cat(
            x.round()
            .toInt64()
            .format()
        )
        .cat("_")
        .cat(
            y.round()
            .toInt64()
            .format()
        )
    )


    def group_id(cell_size):

        gx = (
            x.divide(cell_size)
            .floor()
            .toInt64()
            .format()
        )

        gy = (
            y.divide(cell_size)
            .floor()
            .toInt64()
            .format()
        )

        return (
            ee.String(gx)
            .cat("_")
            .cat(gy)
        )


    return feature.set({

        "SAMPLE_ID":
            sample_id,

        "X_UTM47N":
            x,

        "Y_UTM47N":
            y,

        "SPATIAL_GROUP_250M":
            group_id(250),

        "SPATIAL_GROUP_500M":
            group_id(500),

        "SPATIAL_GROUP_1000M":
            group_id(1000)
    })


sample_fc = sample_fc_raw.map(
    add_sample_metadata
)


