# ============================================================
# 7. SAMPLE EACH SOURCE AT NATIVE/EFFECTIVE SCALE
# ============================================================

def extract_source(
    source_name,
    asset_id,
    bands,
    scale
):

    print("\n" + "-" * 100)
    print(
        f"EXTRACTING {source_name} | "
        f"{len(bands)} bands | "
        f"scale ~{scale} m"
    )
    print("-" * 100)

    source_img = (
        ee.Image(asset_id)
        .select(bands)
        .unmask(NODATA_SENTINEL)
    )

    # Preserve the source projection rather than
    # forcing every context dataset to EPSG:32647.
    source_projection = (
        ee.Image(asset_id)
        .select(bands[0])
        .projection()
    )

    sampled = source_img.sampleRegions(

        collection=sample_fc,

        properties=[
            "SAMPLE_ID"
        ],

        scale=scale,

        projection=source_projection,

        tileScale=4,

        geometries=False
    )


    source_df = feature_collection_to_df(
        sampled
    )


    # ---------------------------------------------
    # QA row count / ID uniqueness
    # ---------------------------------------------

    print(
        "Rows             :",
        len(source_df)
    )

    print(
        "Unique SAMPLE_ID :",
        source_df["SAMPLE_ID"].nunique()
    )

    print(
        "Duplicate IDs    :",
        source_df["SAMPLE_ID"].duplicated().sum()
    )


    # ---------------------------------------------
    # Replace sentinel with NaN
    # ---------------------------------------------

    for b in bands:

        if b not in source_df.columns:

            # This would indicate something unexpected
            # happened during EE sampling.
            source_df[b] = np.nan

        source_df[b] = (
            pd.to_numeric(
                source_df[b],
                errors="coerce"
            )
            .replace(
                NODATA_SENTINEL,
                np.nan
            )
        )


    mean_missing = (
        source_df[bands]
        .isna()
        .mean()
        .mean()
        * 100
    )


    print(
        f"Mean missingness : "
        f"{mean_missing:.3f}%"
    )


    # ---------------------------------------------
    # Keep only SAMPLE_ID + requested bands
    # ---------------------------------------------

    source_df = source_df[
        ["SAMPLE_ID"] + bands
    ]


    return source_df


