# ============================================================
# OUTPUT 3 | 30F-B14A
# SPATIAL CROSS-VALIDATION DESIGN & FOLD AUDIT
#
# Goal:
#   Compare 500 m vs 1 km spatial grouping before model fitting.
#
# IMPORTANT:
#   CONDITION_CLASS / RISK_SCORE come from frozen 30D04.
#   They are internal surrogate/reference targets,
#   NOT independent field ground truth.
# ============================================================

import pandas as pd
import numpy as np

from sklearn.model_selection import StratifiedGroupKFold
import sklearn

print("=" * 100)
print("30F-B14A | SPATIAL CROSS-VALIDATION DESIGN & FOLD AUDIT")
print("=" * 100)

print("scikit-learn version:", sklearn.__version__)


# ============================================================
# 1. BASIC INPUT CHECK
# ============================================================

required_cols = [
    "SAMPLE_ID",
    "CONDITION_CLASS",
    "RISK_SCORE_0_100",
    "SPATIAL_GROUP_500M",
    "SPATIAL_GROUP_1000M"
]

missing_cols = [
    c for c in required_cols
    if c not in model_df.columns
]

if missing_cols:
    raise ValueError(
        f"Missing columns: {missing_cols}"
    )


cv_df = model_df[
    required_cols
].copy()


# ------------------------------------------------------------
# Force consistent types
# ------------------------------------------------------------

cv_df["CONDITION_CLASS"] = (
    pd.to_numeric(
        cv_df["CONDITION_CLASS"],
        errors="raise"
    )
    .astype(int)
)

cv_df["RISK_SCORE_0_100"] = (
    pd.to_numeric(
        cv_df["RISK_SCORE_0_100"],
        errors="raise"
    )
)


print("\nSamples :", len(cv_df))
print(
    "Classes :",
    cv_df["CONDITION_CLASS"]
    .value_counts()
    .sort_index()
    .to_dict()
)

print(
    "500 m groups :",
    cv_df["SPATIAL_GROUP_500M"].nunique()
)

print(
    "1 km groups  :",
    cv_df["SPATIAL_GROUP_1000M"].nunique()
)


# ============================================================
# 2. SPATIAL CV AUDIT FUNCTION
# ============================================================

def audit_spatial_cv(
    df,
    group_col,
    n_splits=5,
    random_state=42
):

    print("\n" + "=" * 100)
    print(f"CV DESIGN: {group_col}")
    print("=" * 100)

    splitter = StratifiedGroupKFold(
        n_splits=n_splits,
        shuffle=True,
        random_state=random_state
    )

    X_dummy = np.zeros(
        (len(df), 1)
    )

    y_strat = df[
        "CONDITION_CLASS"
    ].values

    groups = df[
        group_col
    ].astype(str).values


    fold_assignment = np.full(
        len(df),
        -1,
        dtype=int
    )


    fold_rows = []
    class_rows = []


    for fold_id, (
        train_idx,
        valid_idx
    ) in enumerate(

        splitter.split(
            X_dummy,
            y_strat,
            groups
        ),

        start=1
    ):

        train_df = df.iloc[
            train_idx
        ]

        valid_df = df.iloc[
            valid_idx
        ]


        fold_assignment[
            valid_idx
        ] = fold_id


        # ----------------------------------------------------
        # Group leakage audit
        # ----------------------------------------------------

        train_groups = set(
            train_df[
                group_col
            ].astype(str)
        )

        valid_groups = set(
            valid_df[
                group_col
            ].astype(str)
        )

        overlap = (
            train_groups
            .intersection(
                valid_groups
            )
        )


        # ----------------------------------------------------
        # Fold-level summary
        # ----------------------------------------------------

        fold_rows.append({

            "grouping":
                group_col,

            "fold":
                fold_id,

            "train_n":
                len(train_df),

            "valid_n":
                len(valid_df),

            "train_groups":
                len(train_groups),

            "valid_groups":
                len(valid_groups),

            "group_overlap":
                len(overlap),

            "valid_risk_mean":
                valid_df[
                    "RISK_SCORE_0_100"
                ].mean(),

            "valid_risk_median":
                valid_df[
                    "RISK_SCORE_0_100"
                ].median(),

            "valid_condition_mean":
                valid_df[
                    "CONDITION_CLASS"
                ].mean()
        })


        # ----------------------------------------------------
        # Class distribution per validation fold
        # ----------------------------------------------------

        valid_counts = (
            valid_df[
                "CONDITION_CLASS"
            ]
            .value_counts()
            .sort_index()
        )


        for class_code in [
            1, 2, 3, 4
        ]:

            count = int(
                valid_counts.get(
                    class_code,
                    0
                )
            )

            class_rows.append({

                "grouping":
                    group_col,

                "fold":
                    fold_id,

                "class":
                    class_code,

                "n":
                    count,

                "pct":
                    (
                        count
                        / len(valid_df)
                        * 100
                    )
            })


    fold_summary = pd.DataFrame(
        fold_rows
    )

    class_summary = pd.DataFrame(
        class_rows
    )


    # --------------------------------------------------------
    # Fold assignment QA
    # --------------------------------------------------------

    if np.any(
        fold_assignment < 1
    ):
        raise RuntimeError(
            "Some samples did not receive a fold."
        )


    result_df = df.copy()

    result_df[
        f"FOLD_{group_col}"
    ] = fold_assignment


    # --------------------------------------------------------
    # Print output
    # --------------------------------------------------------

    print("\nFOLD SUMMARY")
    display(
        fold_summary
    )


    print("\nVALIDATION CLASS COUNTS")

    class_pivot = (
        class_summary
        .pivot(
            index="fold",
            columns="class",
            values="n"
        )
        .fillna(0)
        .astype(int)
    )

    class_pivot.columns = [
        f"CLASS_{c}"
        for c in class_pivot.columns
    ]

    display(
        class_pivot
    )


    print("\nVALIDATION CLASS PERCENTAGES")

    class_pct_pivot = (
        class_summary
        .pivot(
            index="fold",
            columns="class",
            values="pct"
        )
    )

    class_pct_pivot.columns = [
        f"CLASS_{c}_PCT"
        for c in class_pct_pivot.columns
    ]

    display(
        class_pct_pivot.round(2)
    )


    # --------------------------------------------------------
    # Stability metrics
    # --------------------------------------------------------

    valid_sizes = (
        fold_summary[
            "valid_n"
        ]
    )

    size_cv = (
        valid_sizes.std()
        / valid_sizes.mean()
    )


    min_class_counts = (
        class_pivot.min()
    )


    max_group_overlap = (
        fold_summary[
            "group_overlap"
        ].max()
    )


    print("\nCV QA METRICS")

    print(
        "Validation size min/max :",
        int(valid_sizes.min()),
        "/",
        int(valid_sizes.max())
    )

    print(
        "Validation size CV      :",
        round(size_cv, 4)
    )

    print(
        "Minimum Class 1 / fold  :",
        int(
            min_class_counts.get(
                "CLASS_1",
                0
            )
        )
    )

    print(
        "Minimum Class 2 / fold  :",
        int(
            min_class_counts.get(
                "CLASS_2",
                0
            )
        )
    )

    print(
        "Minimum Class 3 / fold  :",
        int(
            min_class_counts.get(
                "CLASS_3",
                0
            )
        )
    )

    print(
        "Minimum Class 4 / fold  :",
        int(
            min_class_counts.get(
                "CLASS_4",
                0
            )
        )
    )

    print(
        "Maximum group overlap   :",
        int(
            max_group_overlap
        )
    )


    # --------------------------------------------------------
    # Basic gate
    # --------------------------------------------------------

    leakage_pass = (
        max_group_overlap == 0
    )

    severe_class_pass = (
        min_class_counts.get(
            "CLASS_3",
            0
        ) > 0
        and
        min_class_counts.get(
            "CLASS_4",
            0
        ) > 0
    )


    print("\nBASIC GATE")

    print(
        "No spatial-group leakage :",
        "PASS"
        if leakage_pass
        else "FAIL"
    )

    print(
        "Class 3 present all folds :",
        "PASS"
        if (
            min_class_counts.get(
                "CLASS_3",
                0
            ) > 0
        )
        else "FAIL"
    )

    print(
        "Class 4 present all folds :",
        "PASS"
        if (
            min_class_counts.get(
                "CLASS_4",
                0
            ) > 0
        )
        else "FAIL"
    )


    return {
        "fold_summary":
            fold_summary,

        "class_summary":
            class_summary,

        "class_counts":
            class_pivot,

        "class_pct":
            class_pct_pivot,

        "assignment_df":
            result_df,

        "size_cv":
            size_cv,

        "min_class_counts":
            min_class_counts,

        "leakage_pass":
            leakage_pass,

        "severe_class_pass":
            severe_class_pass
    }


# ============================================================
# 3. AUDIT 500 M GROUPING
