# ============================================================

# ============================================================
# OUTPUT 3 | 30F-B14B
# FIXED-MODEL SPATIAL CV BENCHMARK
# A vs B vs C vs D
#
# CV:
#   Frozen SPATIAL_GROUP_1000M folds from B14A
#
# TARGET:
#   RISK_SCORE_0_100 from frozen 30D04
#
# IMPORTANT:
#   This measures surrogate agreement / reproducibility
#   against 30D04, NOT independent plantation-health accuracy.
#
#   D_FULL_CONTEXT remains sensitivity-only because
#   ERA5/ETPET contain ~4 coarse spatial contexts.
# ============================================================

import pandas as pd
import numpy as np

from pathlib import Path

from sklearn.compose import ColumnTransformer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder
from sklearn.impute import SimpleImputer
from sklearn.ensemble import RandomForestRegressor

from sklearn.metrics import (
    mean_absolute_error,
    mean_squared_error,
    r2_score
)

from scipy.stats import spearmanr


print("=" * 105)
print("30F-B14B | FIXED-MODEL SPATIAL CV BENCHMARK")
print("=" * 105)


# ============================================================
# 1. CONFIGURATION
# ============================================================

TARGET = "RISK_SCORE_0_100"
FOLD_COL = "SPATIAL_CV_FOLD_V1"

RANDOM_STATE = 42

RF_PARAMS = {
    "n_estimators": 500,
    "min_samples_leaf": 3,
    "max_features": "sqrt",
    "random_state": RANDOM_STATE,
    "n_jobs": -1
}


# ============================================================
# 2. INPUT QA
# ============================================================

if TARGET not in model_df.columns:
    raise ValueError(
        f"Target missing: {TARGET}"
    )

if FOLD_COL not in model_df.columns:
    raise ValueError(
        f"Fold column missing: {FOLD_COL}"
    )


expected_folds = [1, 2, 3, 4, 5]

actual_folds = sorted(
    model_df[FOLD_COL]
    .dropna()
    .astype(int)
    .unique()
    .tolist()
)


print("\nSamples :", len(model_df))
print("Folds   :", actual_folds)


if actual_folds != expected_folds:

    raise ValueError(
        f"Expected folds {expected_folds}, "
        f"found {actual_folds}"
    )


# ============================================================
# 3. MODEL FACTORY
#
# Preprocessing is fitted INSIDE each training fold.
# Therefore median imputation / one-hot encoding do not use
# validation-fold information.
# ============================================================

def build_model(
    numeric_features,
    categorical_features
):

    numeric_pipe = Pipeline([
        (
            "imputer",
            SimpleImputer(
                strategy="median"
            )
        )
    ])


    transformers = [
        (
            "numeric",
            numeric_pipe,
            numeric_features
        )
    ]


    if len(categorical_features) > 0:

        categorical_pipe = Pipeline([
            (
                "imputer",
                SimpleImputer(
                    strategy="most_frequent"
                )
            ),
            (
                "onehot",
                OneHotEncoder(
                    handle_unknown="ignore",
                    sparse_output=False
                )
            )
        ])


        transformers.append(
            (
                "categorical",
                categorical_pipe,
                categorical_features
            )
        )


    preprocessor = ColumnTransformer(

        transformers=transformers,

        remainder="drop",

        sparse_threshold=0
    )


    model = RandomForestRegressor(
        **RF_PARAMS
    )


    pipeline = Pipeline([
        (
            "preprocessor",
            preprocessor
        ),
        (
            "model",
            model
        )
    ])


    return pipeline


# ============================================================
# 4. METRIC FUNCTION
# ============================================================

def regression_metrics(
    y_true,
    y_pred
):

    mae = mean_absolute_error(
        y_true,
        y_pred
    )

    rmse = np.sqrt(
        mean_squared_error(
            y_true,
            y_pred
        )
    )

    r2 = r2_score(
        y_true,
        y_pred
    )

    rho_result = spearmanr(
        y_true,
        y_pred,
        nan_policy="omit"
    )

    rho = rho_result.statistic


    medae = np.median(
        np.abs(
            np.asarray(y_true)
            - np.asarray(y_pred)
        )
    )


    return {
        "MAE": mae,
        "RMSE": rmse,
        "R2": r2,
        "SPEARMAN": rho,
        "MEDIAN_AE": medae
    }


# ============================================================
# 5. PREPARE OOF TABLE
# ============================================================

oof_df = model_df[
    [
        "SAMPLE_ID",
        "X_UTM47N",
        "Y_UTM47N",
        "CONDITION_CLASS",
        "RISK_SCORE_0_100",
        "SPATIAL_GROUP_1000M",
        "SPATIAL_CV_FOLD_V1"
    ]
].copy()


# ============================================================
# 6. RUN FIXED 5-FOLD BENCHMARK
# ============================================================

fold_metric_rows = []


for set_name, config in candidate_feature_sets.items():

    print("\n" + "=" * 105)
    print(f"FEATURE SET: {set_name}")
    print("=" * 105)

    numeric_features = (
        config["numeric"]
    )

    categorical_features = (
        config["categorical"]
    )


    print(
        "Numeric features     :",
        len(numeric_features)
    )

    print(
        "Categorical features :",
        len(categorical_features)
    )

    print(
        "Role                 :",
        config["role"]
    )


    # --------------------------------------------
    # Prepare OOF prediction column
    # --------------------------------------------

    pred_col = (
        f"PRED_{set_name}"
    )

    oof_df[pred_col] = np.nan


    # ============================================
    # Fold loop
    # ============================================

    for fold in expected_folds:

        train_mask = (
            model_df[FOLD_COL]
            .astype(int)
            != fold
        )

        valid_mask = (
            model_df[FOLD_COL]
            .astype(int)
            == fold
        )


        train_df = model_df.loc[
            train_mask
        ].copy()

        valid_df = model_df.loc[
            valid_mask
        ].copy()


        feature_fields = (
            numeric_features
            + categorical_features
        )


        X_train = train_df[
            feature_fields
        ]

        X_valid = valid_df[
            feature_fields
        ]


        y_train = train_df[
            TARGET
        ].astype(float)

        y_valid = valid_df[
            TARGET
        ].astype(float)


        # ----------------------------------------
        # Build a fresh model for every fold
        # ----------------------------------------

        pipeline = build_model(
            numeric_features=numeric_features,
            categorical_features=categorical_features
        )


        pipeline.fit(
            X_train,
            y_train
        )


        # ----------------------------------------
        # Train + validation predictions
        # ----------------------------------------

        pred_train = pipeline.predict(
            X_train
        )

        pred_valid = pipeline.predict(
            X_valid
        )


        # ----------------------------------------
        # Store OOF predictions
        # ----------------------------------------

        oof_df.loc[
            valid_mask,
            pred_col
        ] = pred_valid


        # ----------------------------------------
        # Metrics
        # ----------------------------------------

        train_metrics = regression_metrics(
            y_train,
            pred_train
        )

        valid_metrics = regression_metrics(
            y_valid,
            pred_valid
        )


        fold_metric_rows.append({

            "feature_set":
                set_name,

            "role":
                config["role"],

            "fold":
                fold,

            "train_n":
                len(train_df),

            "valid_n":
                len(valid_df),

            "numeric_features":
                len(numeric_features),

            "categorical_features":
                len(categorical_features),

            # Train metrics
            "train_MAE":
                train_metrics["MAE"],

            "train_RMSE":
                train_metrics["RMSE"],

            "train_R2":
                train_metrics["R2"],

            # Validation metrics
            "valid_MAE":
                valid_metrics["MAE"],

            "valid_RMSE":
                valid_metrics["RMSE"],

            "valid_R2":
                valid_metrics["R2"],

            "valid_SPEARMAN":
                valid_metrics["SPEARMAN"],

            "valid_MEDIAN_AE":
                valid_metrics["MEDIAN_AE"],

            # Simple overfit indicators
            "MAE_gap_valid_minus_train":
                (
                    valid_metrics["MAE"]
                    - train_metrics["MAE"]
                ),

            "R2_gap_train_minus_valid":
                (
                    train_metrics["R2"]
                    - valid_metrics["R2"]
                )
        })


        print(
            f"Fold {fold} | "
            f"MAE={valid_metrics['MAE']:.3f} | "
            f"RMSE={valid_metrics['RMSE']:.3f} | "
            f"R2={valid_metrics['R2']:.3f} | "
            f"rho={valid_metrics['SPEARMAN']:.3f}"
        )


# ============================================================
# 7. FOLD METRIC TABLE
# ============================================================

fold_metrics_df = pd.DataFrame(
    fold_metric_rows
)


print("\n" + "=" * 105)
print("PER-FOLD VALIDATION METRICS")
print("=" * 105)


display(
    fold_metrics_df[
        [
            "feature_set",
            "fold",
            "valid_n",
            "valid_MAE",
            "valid_RMSE",
            "valid_R2",
            "valid_SPEARMAN",
            "valid_MEDIAN_AE"
        ]
    ]
)


# ============================================================
# 8. AGGREGATE CV SUMMARY
# ============================================================

benchmark_summary_df = (

    fold_metrics_df

    .groupby(
        [
            "feature_set",
            "role"
        ]
    )

    .agg(

        MAE_mean=(
            "valid_MAE",
            "mean"
        ),

        MAE_sd=(
            "valid_MAE",
            "std"
        ),

        RMSE_mean=(
            "valid_RMSE",
            "mean"
        ),

        RMSE_sd=(
            "valid_RMSE",
            "std"
        ),

        R2_mean=(
            "valid_R2",
            "mean"
        ),

        R2_sd=(
            "valid_R2",
            "std"
        ),

        SPEARMAN_mean=(
            "valid_SPEARMAN",
            "mean"
        ),

        SPEARMAN_sd=(
            "valid_SPEARMAN",
            "std"
        ),

        MEDIAN_AE_mean=(
            "valid_MEDIAN_AE",
            "mean"
        ),

        overfit_MAE_gap_mean=(
            "MAE_gap_valid_minus_train",
            "mean"
        ),

        overfit_R2_gap_mean=(
            "R2_gap_train_minus_valid",
            "mean"
        )
    )

    .reset_index()
)


# Preserve logical set order
set_order = [
    "A_SPATIAL",
    "B_SPATIAL_AGE",
    "C_SPATIAL_AGE_CHIRPS",
    "D_FULL_CONTEXT"
]


benchmark_summary_df[
    "feature_set"
] = pd.Categorical(

    benchmark_summary_df[
        "feature_set"
    ],

    categories=set_order,

    ordered=True
)


benchmark_summary_df = (

    benchmark_summary_df
    .sort_values(
        "feature_set"
    )
    .reset_index(
        drop=True
    )
)


print("\n" + "=" * 105)
print("A vs B vs C vs D | CV SUMMARY")
print("=" * 105)

display(
    benchmark_summary_df
)


# ============================================================
# 9. OOF-LEVEL METRICS
#
# Unlike mean-of-fold metrics, this evaluates all 1300
# held-out predictions together.
# ============================================================

oof_metric_rows = []


for set_name in set_order:

    pred_col = (
        f"PRED_{set_name}"
    )

    valid = (
        oof_df[pred_col]
        .notna()
    )


    metrics = regression_metrics(

        oof_df.loc[
            valid,
            TARGET
        ],

        oof_df.loc[
            valid,
            pred_col
        ]
    )


    oof_metric_rows.append({

        "feature_set":
            set_name,

        "n_oof":
            int(valid.sum()),

        "OOF_MAE":
            metrics["MAE"],

        "OOF_RMSE":
            metrics["RMSE"],

        "OOF_R2":
            metrics["R2"],

        "OOF_SPEARMAN":
            metrics["SPEARMAN"],

        "OOF_MEDIAN_AE":
            metrics["MEDIAN_AE"]
    })


oof_metrics_df = pd.DataFrame(
    oof_metric_rows
)


print("\n" + "=" * 105)
print("OUT-OF-FOLD GLOBAL METRICS")
print("=" * 105)

display(
    oof_metrics_df
)


# ============================================================
# 10. PAIRED INCREMENTAL VALUE VS PREVIOUS SET
#
# Positive MAE improvement means LOWER error.
# Positive R2 delta means BETTER fit.
# ============================================================

comparison_pairs = [

    (
        "A_SPATIAL",
        "B_SPATIAL_AGE",
        "AGE_INCREMENT"
    ),

    (
        "B_SPATIAL_AGE",
        "C_SPATIAL_AGE_CHIRPS",
        "CHIRPS_INCREMENT"
    ),

    (
        "C_SPATIAL_AGE_CHIRPS",
        "D_FULL_CONTEXT",
        "ERA5_ETPET_INCREMENT"
    )
]


increment_rows = []


for base_set, new_set, comparison_name in comparison_pairs:

    base_fold = (
        fold_metrics_df[
            fold_metrics_df[
                "feature_set"
            ] == base_set
        ]
        .sort_values("fold")
        .reset_index(drop=True)
    )

    new_fold = (
        fold_metrics_df[
            fold_metrics_df[
                "feature_set"
            ] == new_set
        ]
        .sort_values("fold")
        .reset_index(drop=True)
    )


    for fold in expected_folds:

        b = base_fold.loc[
            base_fold["fold"] == fold
        ].iloc[0]

        n = new_fold.loc[
            new_fold["fold"] == fold
        ].iloc[0]


        increment_rows.append({

            "comparison":
                comparison_name,

            "base_set":
                base_set,

            "new_set":
                new_set,

            "fold":
                fold,

            # Positive = improvement
            "MAE_improvement":
                (
                    b["valid_MAE"]
                    - n["valid_MAE"]
                ),

            "RMSE_improvement":
                (
                    b["valid_RMSE"]
                    - n["valid_RMSE"]
                ),

            "R2_delta":
                (
                    n["valid_R2"]
                    - b["valid_R2"]
                ),

            "SPEARMAN_delta":
                (
                    n["valid_SPEARMAN"]
                    - b["valid_SPEARMAN"]
                )
        })


increment_df = pd.DataFrame(
    increment_rows
)


increment_summary_df = (

    increment_df

    .groupby(
        [
            "comparison",
            "base_set",
            "new_set"
        ]
    )

    .agg(

        mean_MAE_improvement=(
            "MAE_improvement",
            "mean"
        ),

        mean_RMSE_improvement=(
            "RMSE_improvement",
            "mean"
        ),

        mean_R2_delta=(
            "R2_delta",
            "mean"
        ),

        mean_SPEARMAN_delta=(
            "SPEARMAN_delta",
            "mean"
        ),

        folds_MAE_improved=(
            "MAE_improvement",
            lambda s: int(
                (s > 0).sum()
            )
        ),

        folds_R2_improved=(
            "R2_delta",
            lambda s: int(
                (s > 0).sum()
            )
        )
    )

    .reset_index()
)


print("\n" + "=" * 105)
print("INCREMENTAL VALUE SUMMARY")
