# ============================================================
# 2. CREATE COARSE CONTEXT IDs
#
# Context IDs are derived from complete source signatures,
# NOT from target/risk values.
# ============================================================

def create_context_id(
    df,
    feature_cols,
    output_col,
    decimals=10
):

    tmp = (
        df[feature_cols]
        .copy()
        .round(decimals)
    )

    signature = (
        tmp
        .astype(str)
        .agg("|".join, axis=1)
    )

    codes, uniques = pd.factorize(
        signature,
        sort=True
    )

    df[output_col] = (
        codes + 1
    )

    return len(uniques)


