# ============================================================
# 5. MODEL FACTORY
# ============================================================

def build_model(
    numeric_features,
    categorical_features
):

    numeric_pipe = Pipeline([
        (
            "imputer",
            SimpleImputer(
                strategy="median"
            )
        )
    ])


    transformers = [
        (
            "numeric",
            numeric_pipe,
            numeric_features
        )
    ]


    if categorical_features:

        categorical_pipe = Pipeline([
            (
                "imputer",
                SimpleImputer(
                    strategy="most_frequent"
                )
            ),
            (
                "onehot",
                OneHotEncoder(
                    handle_unknown="ignore",
                    sparse_output=False
                )
            )
        ])

        transformers.append(
            (
                "categorical",
                categorical_pipe,
                categorical_features
            )
        )


    preprocessor = ColumnTransformer(
        transformers=transformers,
        remainder="drop",
        sparse_threshold=0
    )


    return Pipeline([
        (
            "preprocessor",
            preprocessor
        ),
        (
            "model",
            RandomForestRegressor(
                **RF_PARAMS
            )
        )
    ])


# ============================================================
# 6. METRICS
# ============================================================

def regression_metrics(
    y_true,
    y_pred
):

    mae = mean_absolute_error(
        y_true,
        y_pred
    )

    rmse = np.sqrt(
        mean_squared_error(
            y_true,
            y_pred
        )
    )

    r2 = r2_score(
        y_true,
        y_pred
    )

    rho = spearmanr(
        y_true,
        y_pred,
        nan_policy="omit"
    ).statistic


    return {
        "MAE": mae,
        "RMSE": rmse,
        "R2": r2,
        "SPEARMAN": rho
    }


# ============================================================
# 7. GENERIC LEAVE-ONE-CONTEXT-OUT BENCHMARK
# ============================================================

def context_holdout_benchmark(
    df,
    base_set_name,
    new_set_name,
    group_col,
    comparison_name
):

    print("\n" + "=" * 105)
    print(comparison_name)
    print("=" * 105)

    logo = LeaveOneGroupOut()

    groups = (
        df[group_col]
        .values
    )


    base_config = (
        candidate_feature_sets[
            base_set_name
        ]
    )

    new_config = (
        candidate_feature_sets[
            new_set_name
        ]
    )


    result_rows = []

    oof_base = np.full(
        len(df),
        np.nan
    )

    oof_new = np.full(
        len(df),
        np.nan
    )


    dummy_X = np.zeros(
        (len(df), 1)
    )


    split_iterator = logo.split(
        dummy_X,
        groups=groups
    )


    for split_id, (
        train_idx,
        valid_idx
    ) in enumerate(
        split_iterator,
        start=1
    ):

        held_contexts = np.unique(
            groups[valid_idx]
        )

        if len(held_contexts) != 1:
            raise RuntimeError(
                "Expected exactly one held-out context."
            )

        held_context = int(
            held_contexts[0]
        )


        train_df = (
            df.iloc[
                train_idx
            ]
        )

        valid_df = (
            df.iloc[
                valid_idx
            ]
        )


        # ----------------------------------------------------
        # BASE MODEL
        # ----------------------------------------------------

        base_fields = (
            base_config["numeric"]
            + base_config["categorical"]
        )


        base_model = build_model(
            base_config["numeric"],
            base_config["categorical"]
        )


        base_model.fit(
            train_df[base_fields],
            train_df[TARGET]
        )


        pred_base = base_model.predict(
            valid_df[base_fields]
        )


        # ----------------------------------------------------
        # NEW MODEL
        # ----------------------------------------------------

        new_fields = (
            new_config["numeric"]
            + new_config["categorical"]
        )


        new_model = build_model(
            new_config["numeric"],
            new_config["categorical"]
        )


        new_model.fit(
            train_df[new_fields],
            train_df[TARGET]
        )


        pred_new = new_model.predict(
            valid_df[new_fields]
        )


        oof_base[
            valid_idx
        ] = pred_base

        oof_new[
            valid_idx
        ] = pred_new


        base_metrics = regression_metrics(
            valid_df[TARGET],
            pred_base
        )

        new_metrics = regression_metrics(
            valid_df[TARGET],
            pred_new
        )


        result_rows.append({

            "comparison":
                comparison_name,

            "held_context":
                held_context,

            "train_n":
                len(train_idx),

            "valid_n":
                len(valid_idx),

            "risk_mean_valid":
                valid_df[TARGET].mean(),

            "base_set":
                base_set_name,

            "new_set":
                new_set_name,

            "base_MAE":
                base_metrics["MAE"],

            "new_MAE":
                new_metrics["MAE"],

            "MAE_improvement":
                (
                    base_metrics["MAE"]
                    - new_metrics["MAE"]
                ),

            "base_RMSE":
                base_metrics["RMSE"],

            "new_RMSE":
                new_metrics["RMSE"],

            "RMSE_improvement":
                (
                    base_metrics["RMSE"]
                    - new_metrics["RMSE"]
                ),

            "base_R2":
                base_metrics["R2"],

            "new_R2":
                new_metrics["R2"],

            "R2_delta":
                (
                    new_metrics["R2"]
                    - base_metrics["R2"]
                ),

            "base_SPEARMAN":
                base_metrics["SPEARMAN"],

            "new_SPEARMAN":
                new_metrics["SPEARMAN"],

            "SPEARMAN_delta":
                (
                    new_metrics["SPEARMAN"]
                    - base_metrics["SPEARMAN"]
                )
        })


        print(
            f"Context {held_context:2d} | "
            f"n={len(valid_idx):4d} | "
            f"MAE improvement="
            f"{base_metrics['MAE'] - new_metrics['MAE']:+.3f} | "
            f"R2 delta="
            f"{new_metrics['R2'] - base_metrics['R2']:+.3f}"
        )


    results_df = pd.DataFrame(
        result_rows
    )


    # --------------------------------------------------------
    # Global OOF metrics
    # --------------------------------------------------------

    target_values = (
        df[TARGET]
        .astype(float)
        .values
    )


    base_global = regression_metrics(
        target_values,
        oof_base
    )

    new_global = regression_metrics(
        target_values,
        oof_new
    )


    global_df = pd.DataFrame([
        {
            "comparison":
                comparison_name,

            "base_set":
                base_set_name,

            "new_set":
                new_set_name,

            "n_contexts":
                df[group_col].nunique(),

            "OOF_base_MAE":
                base_global["MAE"],

            "OOF_new_MAE":
                new_global["MAE"],

            "OOF_MAE_improvement":
                (
                    base_global["MAE"]
                    - new_global["MAE"]
                ),

            "OOF_base_RMSE":
                base_global["RMSE"],

            "OOF_new_RMSE":
                new_global["RMSE"],

            "OOF_RMSE_improvement":
                (
                    base_global["RMSE"]
                    - new_global["RMSE"]
                ),

            "OOF_base_R2":
                base_global["R2"],

            "OOF_new_R2":
                new_global["R2"],

            "OOF_R2_delta":
                (
                    new_global["R2"]
                    - base_global["R2"]
                ),

            "OOF_base_SPEARMAN":
                base_global["SPEARMAN"],

            "OOF_new_SPEARMAN":
                new_global["SPEARMAN"],

            "OOF_SPEARMAN_delta":
                (
                    new_global["SPEARMAN"]
                    - base_global["SPEARMAN"]
                ),

            "contexts_MAE_improved":
                int(
                    (
                        results_df[
                            "MAE_improvement"
                        ] > 0
                    ).sum()
                ),

            "contexts_R2_improved":
                int(
                    (
                        results_df[
                            "R2_delta"
                        ] > 0
                    ).sum()
                )
        }
    ])


    return (
        results_df,
        global_df,
        oof_base,
        oof_new
    )


