#
# Direct semantic mapping from Output 2.
#
# 0 = no event detected 2001-2025
# 1 = event 2001-2005
# 2 = event 2006-2010
# 3 = event 2011-2015
# 4 = event 2016-2020
# 5 = event 2021-2025
# 9 = missing age context
#
