# ============================================================
# 2. ADD EXPLICIT WGS84 COORDINATES TO FROZEN sample_fc
# ============================================================

def add_wgs84_coordinates(feature):

    geom_wgs84 = (
        feature
        .geometry()
        .transform(
            "EPSG:4326",
            1
        )
    )

    coords = ee.List(
        geom_wgs84.coordinates()
    )

    lon = ee.Number(
        coords.get(0)
    )

    lat = ee.Number(
        coords.get(1)
    )


    return feature.set({
        "LON_WGS84": lon,
        "LAT_WGS84": lat
    })


sample_geo_fc = (
    sample_fc
    .map(
        add_wgs84_coordinates
    )
)


