def setup_map_axes(title):

    fig, ax = plt.subplots(
        figsize=(9, 8)
    )

    ax.set_title(
        title,
        fontsize=13
    )

    ax.set_xlabel(
        "UTM Zone 47N Easting (km)"
    )

    ax.set_ylabel(
        "UTM Zone 47N Northing (km)"
    )

    ax.set_xlim(
        xmin - xpad,
        xmax + xpad
    )

    ax.set_ylim(
        ymin - ypad,
        ymax + ypad
    )

    ax.set_aspect(
        "equal",
        adjustable="box"
    )

    ax.grid(
        True,
        alpha=0.2
    )

    return fig, ax


