# ============================================================
# OUTPUT 3 | 30F-B18A
# EVIDENCE-BASED PARAMETER PRIORITIZATION V1
#
# Purpose:
# Rank the 21 retained spatial/environmental features
# BEFORE building any integrated scoring model.
#
# IMPORTANT:
# - Correlation is association, NOT causality.
# - Tiering is a pilot prioritization rule.
# - It does NOT yet define final fusion weights.
# ============================================================

import pandas as pd
import numpy as np
from scipy.stats import spearmanr
from pathlib import Path

print("=" * 110)
print("30F-B18A | EVIDENCE-BASED PARAMETER PRIORITIZATION V1")
print("=" * 110)

checkpoint_dir = Path("checkpoints_30F")
checkpoint_dir.mkdir(parents=True, exist_ok=True)


# ============================================================
# 1. INPUT
# ============================================================

if "model_df" not in globals():

    model_df = pd.read_pickle(
        checkpoint_dir /
        "30F_B16_CONTEXT_ENRICHED_SAMPLE_V1.pkl"
    )


if len(vif_features) != 21:
    raise ValueError(
        f"Expected 21 frozen B10 features, found {len(vif_features)}"
    )


TARGET = "RISK_SCORE_0_100"


# ============================================================
# 2. FEATURE FAMILY + EFFECTIVE SCALE
# ============================================================

def classify_family(feature):

    terrain = {
        "LOCAL_RELIEF_300M_M",
        "TPI_300M_M",
        "TPI_90M_M",
        "SLOPE_DEG",
        "ASPECT_SIN",
        "ASPECT_COS"
    }

    hydrology = {
        "HAND_M",
        "LOG10_UPA"
    }

    soil_water = {
        "WV1500_SURFACE_0_30CM",
        "WV1500_DEEP_100_200CM",
        "PAW_PROXY_SURFACE_0_30CM",
        "WV10_DEEP_100_200CM"
    }


    if feature in terrain:
        return "TERRAIN", 30.922

    elif feature in hydrology:
        return "HYDROLOGY", 92.766

    elif feature in soil_water:
        return "SOIL_WATER", 258.75

    else:
        return "SOIL", 250.0


# ============================================================
# 3. FEATURE-LEVEL EVIDENCE
# ============================================================

rows = []

for feature in vif_features:

    x = pd.to_numeric(
        model_df[feature],
        errors="coerce"
    )

    y = pd.to_numeric(
        model_df[TARGET],
        errors="coerce"
    )

    valid = (
        x.notna()
        & y.notna()
    )


    rho = spearmanr(
        x[valid],
        y[valid]
    ).statistic


    family, scale_m = classify_family(
        feature
    )


    missing_pct = (
        x.isna().mean()
        * 100
    )


    n_unique = (
        x.dropna().nunique()
    )


    rows.append({

        "feature":
            feature,

        "family":
            family,

        "effective_scale_m":
            scale_m,

        "n_valid":
            int(valid.sum()),

        "missing_pct":
            float(missing_pct),

        "n_unique":
            int(n_unique),

        "spearman_risk":
            float(rho),

        "abs_spearman":
            float(abs(rho)),

        "vif_retained":
            True
    })


parameter_evidence_df = pd.DataFrame(
    rows
)


# ============================================================
# 4. PILOT PRIORITY RULE
#
# P1:
#   |rho| >= 0.25
#   coverage >= 95%
#   effective scale <= 300 m
#
# P2:
#   |rho| >= 0.15
#   coverage >= 95%
#   effective scale <= 300 m
#
# P3:
#   retained feature but weak association
#
# Thresholds are PILOT screening rules only.
# ============================================================

def assign_priority(row):

    coverage_ok = (
        row["missing_pct"] <= 5
    )

    scale_ok = (
        row["effective_scale_m"] <= 300
    )


    if (
        row["abs_spearman"] >= 0.25
        and coverage_ok
        and scale_ok
    ):
        return "P1_MODIFIER_CANDIDATE"

    elif (
        row["abs_spearman"] >= 0.15
        and coverage_ok
        and scale_ok
    ):
        return "P2_SUPPORTING_MODIFIER"

    else:
        return "P3_CONTEXT_ONLY"


parameter_evidence_df[
    "priority_tier"
] = parameter_evidence_df.apply(
    assign_priority,
    axis=1
)


