# ============================================================
# ORIGINAL NOTEBOOK CELL 52
# ============================================================

# ============================================================
# OUTPUT 3 | 30F-B18C
# FAMILY-BALANCED DIRECTIONAL CONTEXT MODIFIER V1
#
# Purpose:
# 1. Derive robust wall-to-wall P10/P50/P90 calibration
#    from the full valid AOI01 core mask.
# 2. Directional-normalize the 8 B18B eligible features.
# 3. Combine features WITHIN families using evidence weights.
# 4. Combine families using family-balanced evidence weights.
#
# OUTPUT:
#   CONTEXT_MODIFIER_SCORE in [-1, +1]
#
# IMPORTANT:
# - DOES NOT modify RISK_SCORE yet.
# - DOES NOT modify CONDITION_CLASS yet.
# - AOI01 calibration is PILOT calibration.
# - It will later be frozen and tested unchanged on AOI02.
# ============================================================

import ee
import pandas as pd
import numpy as np
import json
from pathlib import Path

print("=" * 115)
print("30F-B18C | FAMILY-BALANCED DIRECTIONAL CONTEXT MODIFIER V1")
print("=" * 115)

checkpoint_dir = Path("checkpoints_30F")
checkpoint_dir.mkdir(parents=True, exist_ok=True)


# ============================================================
# 1. RESTORE REQUIRED TABLES IF NEEDED
# ============================================================

if "model_df" not in globals():
    model_df = pd.read_pickle(
        checkpoint_dir /
        "30F_B16_CONTEXT_ENRICHED_SAMPLE_V1.pkl"
    )

if "parameter_evidence_df" not in globals():
    parameter_evidence_df = pd.read_csv(
        checkpoint_dir /
        "30F_B18A_PARAMETER_PRIORITY_V1.csv"
    )

if "spatial_stability_df" not in globals():
    spatial_stability_df = pd.read_csv(
        checkpoint_dir /
        "30F_B18B_SPATIAL_STABILITY_V1.csv"
    )


# ============================================================
# 2. ELIGIBLE FEATURES
# ============================================================

eligible_df = (
    spatial_stability_df[
        spatial_stability_df[
            "fusion_eligible_v1"
        ].astype(str).str.lower().isin(["true", "1"])
        if spatial_stability_df[
            "fusion_eligible_v1"
        ].dtype == object
        else spatial_stability_df[
            "fusion_eligible_v1"
        ]
    ]
    .copy()
)


# Fallback if CSV boolean parsing behaved differently
if len(eligible_df) == 0:

    eligible_df = spatial_stability_df[
        spatial_stability_df[
            "stability_status"
        ].isin([
            "STABLE_STRONG",
            "STABLE_MODERATE"
        ])
    ].copy()


eligible_features = (
    eligible_df["feature"]
    .tolist()
)


print("\nFusion-eligible features:", len(eligible_features))
print(eligible_features)


if len(eligible_features) != 8:
    raise ValueError(
        f"Expected 8 eligible features, found "
        f"{len(eligible_features)}"
    )


# ============================================================
# 3. FEATURE SOURCE REGISTRY
# ============================================================

feature_source_registry = {

    # TERRAIN
    "LOCAL_RELIEF_300M_M": {
        "family": "TERRAIN",
        "asset": ASSETS["TERRAIN"],
        "scale": 30.922
    },

    "SLOPE_DEG": {
        "family": "TERRAIN",
        "asset": ASSETS["TERRAIN"],
        "scale": 30.922
    },


    # HYDROLOGY
    "HAND_M": {
        "family": "HYDROLOGY",
        "asset": ASSETS["HYDRO"],
        "scale": 92.766
    },


    # SOIL
    "SILT_PCT_DEEP_100_200CM": {
        "family": "SOIL",
        "asset": ASSETS["SOIL"],
        "scale": 250
    },

    "SOC_GKG_SURFACE_0_30CM": {
        "family": "SOIL",
        "asset": ASSETS["SOIL"],
        "scale": 250
    },


    # SOIL WATER
    "WV1500_DEEP_100_200CM": {
        "family": "SOIL_WATER",
        "asset": ASSETS["SOIL_WATER"],
        "scale": 258.75
    },

    "WV10_DEEP_100_200CM": {
        "family": "SOIL_WATER",
        "asset": ASSETS["SOIL_WATER"],
        "scale": 258.75
    },

    "PAW_PROXY_SURFACE_0_30CM": {
        "family": "SOIL_WATER",
        "asset": ASSETS["SOIL_WATER"],
        "scale": 258.75
    }
}


missing_registry = [
    f for f in eligible_features
    if f not in feature_source_registry
]

if missing_registry:
    raise ValueError(
        f"Missing feature registry entries: "
        f"{missing_registry}"
    )


# ============================================================
# 4. CORE VALID MASK
# ============================================================

core_img = ee.Image(
    ASSETS["CORE"]
)

condition_img = (
    core_img
    .select("CONDITION_CLASS")
)

valid_core_mask = (
    condition_img.gte(1)
    .And(
        condition_img.lte(4)
    )
)


# ============================================================
# 5. WALL-TO-WALL ROBUST CALIBRATION
#
# Percentiles are calculated feature-by-feature
# at the source's native/effective scale.
#
# We deliberately DO NOT compute normalization from
# the risk-stratified 1300-sample distribution.
# ============================================================

calibration_rows = []


print("\n" + "=" * 115)
print("WALL-TO-WALL ROBUST CALIBRATION | AOI01")
print("=" * 115)


for feature in eligible_features:

    spec = feature_source_registry[
        feature
    ]

    source_img = (
        ee.Image(
            spec["asset"]
        )
        .select(feature)
        .updateMask(
            valid_core_mask
        )
    )


    reducer = (
        ee.Reducer.percentile(
            [10, 50, 90]
        )
        .combine(
            ee.Reducer.count(),
            sharedInputs=True
        )
    )


    stats = (
        source_img
        .reduceRegion(
            reducer=reducer,
            geometry=core_img.geometry(),
            scale=spec["scale"],
            maxPixels=1e8,
            tileScale=4
        )
        .getInfo()
    )


    p10 = stats.get(
        f"{feature}_p10"
    )

    p50 = stats.get(
        f"{feature}_p50"
    )

    p90 = stats.get(
        f"{feature}_p90"
    )

    count = stats.get(
        f"{feature}_count"
    )


    if (
        p10 is None
        or p50 is None
        or p90 is None
    ):

        raise ValueError(
            f"Percentile calibration failed "
            f"for {feature}"
        )


    if float(p90) <= float(p10):

        raise ValueError(
            f"Invalid P10/P90 range for "
            f"{feature}: {p10}, {p90}"
        )


    # ---------------------------------------------
    # Association direction from B18A
    # ---------------------------------------------

    global_rho = float(

        parameter_evidence_df.loc[
            parameter_evidence_df[
                "feature"
            ] == feature,
            "spearman_risk"
        ].iloc[0]
    )


    direction = (
        1
        if global_rho > 0
        else -1
    )


    stability_row = (
        spatial_stability_df[
            spatial_stability_df[
                "feature"
            ] == feature
        ]
        .iloc[0]
    )


    evidence_strength = float(
        stability_row[
            "median_abs_fold_rho"
        ]
    )


    calibration_rows.append({

        "feature":
            feature,

        "family":
            spec["family"],

        "effective_scale_m":
            spec["scale"],

        "p10":
            float(p10),

        "p50":
            float(p50),

        "p90":
            float(p90),

        "pixel_count":
            int(count),

        "association_direction":
            direction,

        "global_rho":
            global_rho,

        "median_abs_fold_rho":
            evidence_strength,

        "stability_status":
            stability_row[
                "stability_status"
            ]
    })


    print(
        f"{feature:35s} | "
        f"P10={float(p10):10.4f} | "
        f"P50={float(p50):10.4f} | "
        f"P90={float(p90):10.4f} | "
        f"dir={direction:+d}"
    )


calibration_df = pd.DataFrame(
    calibration_rows
)


# ============================================================
# 6. WITHIN-FAMILY EVIDENCE WEIGHTS
#
# Weight = median absolute fold Spearman,
# normalized to sum to 1 WITHIN each family.
#
# Therefore multiple features from one family
# cannot automatically dominate the entire modifier.
# ============================================================

calibration_df[
    "within_family_weight"
] = (

    calibration_df[
        "median_abs_fold_rho"
    ]

    /

    calibration_df
    .groupby("family")[
        "median_abs_fold_rho"
    ]
    .transform("sum")
)


# ============================================================
# 7. FAMILY EVIDENCE STRENGTH
#
# Family strength = median feature-level stability
# within each family.
#
# These are then normalized across families.
# ============================================================

family_weight_df = (

    calibration_df

    .groupby(
        "family"
    )

    .agg(

        n_features=(
            "feature",
            "count"
        ),

        family_evidence_strength=(
            "median_abs_fold_rho",
            "median"
        )
    )

    .reset_index()
)


family_weight_df[
    "family_weight"
] = (

    family_weight_df[
        "family_evidence_strength"
    ]

    /

    family_weight_df[
        "family_evidence_strength"
    ].sum()
)


print("\n" + "=" * 115)
print("WITHIN-FAMILY FEATURE WEIGHTS")
print("=" * 115)

display(
    calibration_df[
        [
            "feature",
            "family",
            "association_direction",
            "median_abs_fold_rho",
            "within_family_weight"
        ]
    ]
)


print("\n" + "=" * 115)
print("FAMILY WEIGHTS")
print("=" * 115)

display(
    family_weight_df
)


# ============================================================
# 8. ROBUST DIRECTIONAL NORMALIZATION ON SAMPLE TABLE
#
# Step A:
# P10 -> 0
# P90 -> 1
# clipped outside that interval.
#
# Step B:
# negative associations are inverted.
#
# Step C:
# convert [0,1] -> [-1,+1]
#
# +1 = stronger context in the direction associated
#      with higher 30D04 risk
#
# -1 = opposite directional context
# ============================================================

fusion_df = model_df.copy()


normalized_feature_cols = []


for _, row in calibration_df.iterrows():

    feature = row[
        "feature"
    ]

    p10 = float(
        row["p10"]
    )

    p90 = float(
        row["p90"]
    )

    direction = int(
        row[
            "association_direction"
        ]
    )


    x = pd.to_numeric(
        fusion_df[feature],
        errors="coerce"
    )


    norm01 = (
        (x - p10)
        /
        (p90 - p10)
    )


    norm01 = norm01.clip(
        lower=0,
        upper=1
    )


    if direction < 0:

        directional01 = (
            1 - norm01
        )

    else:

        directional01 = norm01


    directional_score = (
        directional01 * 2
        - 1
    )


    output_col = (
        f"DIR_{feature}"
    )


    fusion_df[
        output_col
    ] = directional_score


    normalized_feature_cols.append(
        output_col
    )


# ============================================================
# 9. FAMILY COMPOSITES
#
# Missing values:
# use only available feature weights within each family,
# then renormalize those available weights.
#
# Require >=50% of family weight to be available.
# ============================================================

family_score_cols = []


for family in (
    family_weight_df[
        "family"
    ].tolist()
):

    family_cal = (
        calibration_df[
            calibration_df[
                "family"
            ] == family
        ]
        .copy()
    )


    weighted_sum = pd.Series(
        0.0,
        index=fusion_df.index
    )


    available_weight = pd.Series(
        0.0,
        index=fusion_df.index
    )


    for _, row in family_cal.iterrows():

        feature = row[
            "feature"
        ]

        weight = float(
            row[
                "within_family_weight"
            ]
        )

        col = (
            f"DIR_{feature}"
        )


        valid = (
            fusion_df[col]
            .notna()
        )


        weighted_sum.loc[
            valid
        ] += (
            fusion_df.loc[
                valid,
                col
            ]
            * weight
        )


        available_weight.loc[
            valid
        ] += weight


    family_score = (
        weighted_sum
        /
        available_weight.replace(
            0,
            np.nan
        )
    )


    # Require at least half of the
    # within-family evidence weight.
    family_score[
        available_weight < 0.50
    ] = np.nan


    score_col = (
        f"FAMILY_SCORE_{family}"
    )


    coverage_col = (
        f"FAMILY_COVERAGE_{family}"
    )


    fusion_df[
        score_col
    ] = family_score.clip(
        -1,
        1
    )


    fusion_df[
        coverage_col
    ] = available_weight


    family_score_cols.append(
        score_col
    )


# ============================================================
# 10. OVERALL CONTEXT MODIFIER SCORE
#
# Family-balanced evidence-weighted combination.
#
# Output remains [-1,+1].
#
# It is NOT yet added to core risk.
# ============================================================

overall_weighted_sum = pd.Series(
    0.0,
    index=fusion_df.index
)

overall_available_weight = pd.Series(
    0.0,
    index=fusion_df.index
)


for _, row in family_weight_df.iterrows():

    family = row[
        "family"
    ]

    family_weight = float(
        row[
            "family_weight"
        ]
    )

    col = (
        f"FAMILY_SCORE_{family}"
    )

    valid = (
        fusion_df[col]
        .notna()
    )


    overall_weighted_sum.loc[
        valid
    ] += (
        fusion_df.loc[
            valid,
            col
        ]
        * family_weight
    )


    overall_available_weight.loc[
        valid
    ] += family_weight


fusion_df[
    "CONTEXT_MODIFIER_SCORE"
] = (

    overall_weighted_sum
    /
    overall_available_weight.replace(
        0,
        np.nan
    )

).clip(
    -1,
    1
)


fusion_df[
    "CONTEXT_MODIFIER_COVERAGE"
] = (
    overall_available_weight
)


# Require >=75% of family evidence weight
fusion_df.loc[
    fusion_df[
        "CONTEXT_MODIFIER_COVERAGE"
    ] < 0.75,
    "CONTEXT_MODIFIER_SCORE"
] = np.nan


# ============================================================
# 11. SAMPLE-LEVEL QA
# ============================================================

print("\n" + "=" * 115)
print("CONTEXT MODIFIER QA")
print("=" * 115)


modifier_valid = (
    fusion_df[
        "CONTEXT_MODIFIER_SCORE"
    ]
    .notna()
)


print(
    "Valid modifier samples :",
    int(
        modifier_valid.sum()
    ),
    "/",
    len(fusion_df)
)


print(
    "Modifier min           :",
    fusion_df[
        "CONTEXT_MODIFIER_SCORE"
    ].min()
)

print(
    "Modifier median        :",
    fusion_df[
        "CONTEXT_MODIFIER_SCORE"
    ].median()
)

print(
    "Modifier mean          :",
    fusion_df[
        "CONTEXT_MODIFIER_SCORE"
    ].mean()
)

print(
    "Modifier max           :",
    fusion_df[
        "CONTEXT_MODIFIER_SCORE"
    ].max()
)


modifier_rho = (
    fusion_df.loc[
        modifier_valid,
        "CONTEXT_MODIFIER_SCORE"
    ]
    .corr(
        fusion_df.loc[
            modifier_valid,
            "RISK_SCORE_0_100"
        ],
        method="spearman"
    )
)


print(
    "Spearman modifier vs core risk:",
    round(
        modifier_rho,
        4
    )
)


# ============================================================
# 12. MODIFIER BY CONDITION CLASS
#
# Diagnostic only.
# ============================================================

modifier_class_summary_df = (

    fusion_df

    .groupby(
        "CONDITION_CLASS"
    )

    .agg(

        n=(
            "CONTEXT_MODIFIER_SCORE",
            "count"
        ),

        modifier_mean=(
            "CONTEXT_MODIFIER_SCORE",
            "mean"
        ),

        modifier_median=(
            "CONTEXT_MODIFIER_SCORE",
            "median"
        ),

        modifier_p25=(
            "CONTEXT_MODIFIER_SCORE",
            lambda s:
                s.quantile(0.25)
        ),

        modifier_p75=(
            "CONTEXT_MODIFIER_SCORE",
            lambda s:
                s.quantile(0.75)
        )
    )

    .reset_index()
)


print("\n" + "=" * 115)
print("CONTEXT MODIFIER BY CONDITION CLASS")
print("=" * 115)

display(
    modifier_class_summary_df
)


# ============================================================
# 13. FOLD STABILITY OF FINAL MODIFIER
# ============================================================

modifier_fold_rows = []


for fold in sorted(
    fusion_df[
        "SPATIAL_CV_FOLD_V1"
    ]
    .dropna()
    .astype(int)
    .unique()
):

    subset = (
        fusion_df[
            fusion_df[
                "SPATIAL_CV_FOLD_V1"
            ].astype(int) == fold
        ]
        .dropna(
            subset=[
                "CONTEXT_MODIFIER_SCORE",
                "RISK_SCORE_0_100"
            ]
        )
    )


    rho = (
        subset[
            "CONTEXT_MODIFIER_SCORE"
        ]
        .corr(
            subset[
                "RISK_SCORE_0_100"
            ],
            method="spearman"
        )
    )


    modifier_fold_rows.append({

        "fold":
            fold,

        "n":
            len(subset),

        "spearman_modifier_vs_risk":
            rho,

        "modifier_mean":
            subset[
                "CONTEXT_MODIFIER_SCORE"
            ].mean(),

        "modifier_sd":
            subset[
                "CONTEXT_MODIFIER_SCORE"
            ].std()
    })


modifier_fold_qc_df = pd.DataFrame(
    modifier_fold_rows
)


print("\n" + "=" * 115)
print("MODIFIER SPATIAL-FOLD QA")
print("=" * 115)

display(
    modifier_fold_qc_df
)


# ============================================================
# 14. AOI01 CALIBRATION CLIPPING QA
#
