import pandas as pd
import numpy as np
from scipy.stats import spearmanr
from pathlib import Path

print("=" * 115)
print("30F-B18D1 | BOUNDED FUSION AMPLITUDE + CORE CLASS/RISK AUDIT")
print("=" * 115)

checkpoint_dir = Path("checkpoints_30F")

TARGET = "RISK_SCORE_0_100"
CLASS = "CONDITION_CLASS"
MODIFIER = "CONTEXT_MODIFIER_SCORE"


# ============================================================
# 1. RESTORE B18C IF NEEDED
# ============================================================

if "fusion_df" not in globals():

    fusion_df = pd.read_pickle(
        checkpoint_dir /
        "30F_B18C_FUSION_SAMPLE_V1.pkl"
    )


fusion_test_df = fusion_df.copy()


# ============================================================
# 2. MODIFIER AVAILABILITY
#
# If modifier is missing, production-safe fallback:
# adjustment = 0 -> retain original core risk.
# ============================================================

fusion_test_df[
    "MODIFIER_AVAILABLE"
] = (
    fusion_test_df[
        MODIFIER
    ].notna()
)


fusion_test_df[
    "MODIFIER_FOR_FUSION"
] = (
    fusion_test_df[
        MODIFIER
    ].fillna(0)
)


print(
    "\nModifier available:",
    int(
        fusion_test_df[
            "MODIFIER_AVAILABLE"
        ].sum()
    ),
    "/",
    len(fusion_test_df)
)


# ============================================================
# 3. CORE CLASS vs CORE RISK AUDIT
# ============================================================

def q05(x):
    return x.quantile(0.05)

def q25(x):
    return x.quantile(0.25)

def q75(x):
    return x.quantile(0.75)

def q95(x):
    return x.quantile(0.95)


core_class_risk_df = (

    fusion_test_df

    .groupby(
        CLASS
    )

    .agg(

        n=(
            TARGET,
            "count"
        ),

        risk_min=(
            TARGET,
            "min"
        ),

        risk_p05=(
            TARGET,
            q05
        ),

        risk_p25=(
            TARGET,
            q25
        ),

        risk_median=(
            TARGET,
            "median"
        ),

        risk_mean=(
            TARGET,
            "mean"
        ),

        risk_p75=(
            TARGET,
            q75
        ),

        risk_p95=(
            TARGET,
            q95
        ),

        risk_max=(
            TARGET,
            "max"
        ),

        n_unique_risk=(
            TARGET,
            "nunique"
        )
    )

    .reset_index()
)


print("\n" + "=" * 115)
print("CORE RISK DISTRIBUTION BY CONDITION CLASS")
print("=" * 115)

display(
    core_class_risk_df
)


# ============================================================
# 4. TEST WHETHER RISK -> CLASS IS A SIMPLE UNIQUE MAPPING
# ============================================================

risk_class_mapping = (

    fusion_test_df

    .groupby(
        TARGET
    )[CLASS]

    .nunique()
)


shared_risk_values = (
    risk_class_mapping
    > 1
)


n_shared_risk_values = int(
    shared_risk_values.sum()
)


print("\n" + "=" * 115)
print("CORE SCORE -> CLASS MAPPING AUDIT")
print("=" * 115)

print(
    "Unique risk values appearing in >1 class:",
    n_shared_risk_values
)


# Range overlap between adjacent classes
overlap_rows = []


for lower_class, upper_class in [
    (1, 2),
    (2, 3),
    (3, 4)
]:

    lower = fusion_test_df.loc[
        fusion_test_df[
            CLASS
        ] == lower_class,
        TARGET
    ]

    upper = fusion_test_df.loc[
        fusion_test_df[
            CLASS
        ] == upper_class,
        TARGET
    ]


    overlap_low = max(
        lower.min(),
        upper.min()
    )

    overlap_high = min(
        lower.max(),
        upper.max()
    )


    overlap_exists = (
        overlap_high
        >= overlap_low
    )


    overlap_rows.append({

        "class_pair":
            f"{lower_class}-{upper_class}",

        "lower_class_min":
            lower.min(),

        "lower_class_max":
            lower.max(),

        "upper_class_min":
            upper.min(),

        "upper_class_max":
            upper.max(),

        "range_overlap":
            overlap_exists,

        "overlap_low":
            overlap_low
            if overlap_exists
            else np.nan,

        "overlap_high":
            overlap_high
            if overlap_exists
            else np.nan
    })


class_overlap_df = pd.DataFrame(
    overlap_rows
)


display(
    class_overlap_df
)


# ============================================================
# 5. BUILD FUSION SCORE PROTOTYPES
# ============================================================

AMPLITUDES = {
    "F0_CORE": 0,
    "F05_CORE_PLUS_CONTEXT": 5,
    "F10_CORE_PLUS_CONTEXT": 10,
    "F15_CORE_PLUS_CONTEXT": 15
}


for name, amplitude in AMPLITUDES.items():

    fusion_test_df[
        f"SCORE_{name}"
    ] = (

        fusion_test_df[
            TARGET
        ]

        +

        amplitude
        * fusion_test_df[
            "MODIFIER_FOR_FUSION"
        ]

    ).clip(
        0,
        100
    )


    fusion_test_df[
        f"DELTA_{name}"
    ] = (

        fusion_test_df[
            f"SCORE_{name}"
        ]

        -

        fusion_test_df[
            TARGET
        ]
    )


# ============================================================
# 6. SCORE DISPLACEMENT QA
# ============================================================

displacement_rows = []


for name, amplitude in AMPLITUDES.items():

    delta = (
        fusion_test_df[
            f"DELTA_{name}"
        ]
    )


    displacement_rows.append({

        "prototype":
            name,

        "amplitude":
            amplitude,

        "mean_delta":
            delta.mean(),

        "median_delta":
            delta.median(),

        "mean_abs_delta":
            delta.abs().mean(),

        "median_abs_delta":
            delta.abs().median(),

        "p90_abs_delta":
            delta.abs().quantile(0.90),

        "max_abs_delta":
            delta.abs().max(),

        "pct_abs_delta_ge_5":
            (
                delta.abs()
                >= 5
            ).mean() * 100,

        "pct_abs_delta_ge_10":
            (
                delta.abs()
                >= 10
            ).mean() * 100
    })


fusion_displacement_df = pd.DataFrame(
    displacement_rows
)


print("\n" + "=" * 115)
print("FUSION SCORE DISPLACEMENT")
print("=" * 115)

display(
    fusion_displacement_df
)


# ============================================================
# 7. SCORE BEHAVIOUR BY ORIGINAL CLASS
# ============================================================

class_score_rows = []


for name in AMPLITUDES.keys():

    score_col = (
        f"SCORE_{name}"
    )


    for condition_class in [
        1, 2, 3, 4
    ]:

        subset = fusion_test_df[
            fusion_test_df[
                CLASS
            ] == condition_class
        ]


        class_score_rows.append({

            "prototype":
                name,

            "condition_class":
                condition_class,

            "n":
                len(subset),

            "score_mean":
                subset[
                    score_col
                ].mean(),

            "score_median":
                subset[
                    score_col
                ].median(),

            "score_p25":
                subset[
                    score_col
                ].quantile(0.25),

            "score_p75":
                subset[
                    score_col
                ].quantile(0.75)
        })


fusion_class_score_df = pd.DataFrame(
    class_score_rows
)


print("\n" + "=" * 115)
print("FUSION SCORE BY ORIGINAL CONDITION CLASS")
print("=" * 115)

display(
    fusion_class_score_df
)


# ============================================================
# 8. ORDINAL SEPARATION QA
#
# Diagnostic only.
# Higher rho means stronger ordering with current
# CONDITION_CLASS.
#
# This is NOT independent validation.
# ============================================================

ordinal_rows = []


for name in AMPLITUDES.keys():

    score_col = (
        f"SCORE_{name}"
    )


    rho_class = spearmanr(

        fusion_test_df[
            score_col
        ],

        fusion_test_df[
            CLASS
        ]

    ).statistic


    rho_core = spearmanr(

        fusion_test_df[
            score_col
        ],

        fusion_test_df[
            TARGET
        ]

    ).statistic


    ordinal_rows.append({

        "prototype":
            name,

        "spearman_score_vs_condition_class":
            rho_class,

        "spearman_score_vs_core_risk":
            rho_core
    })


fusion_ordinal_df = pd.DataFrame(
    ordinal_rows
)


print("\n" + "=" * 115)
print("ORDINAL SEPARATION QA")
